import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Agnes AI","description":"Agnes AI kostenlose multimodale API — Website, Free Access Key, Text-/Bild-/Videomodelle und Eintrag in MiniTavern.","frontmatter":{"title":"Agnes AI","description":"Agnes AI kostenlose multimodale API — Website, Free Access Key, Text-/Bild-/Videomodelle und Eintrag in MiniTavern.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI kostenlose multimodale API — Website, Free Access Key, Text-/Bild-/Videomodelle und Eintrag in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"de/free-cloud/agnes-ai.md","filePath":"de/free-cloud/agnes-ai.md","lastUpdated":1787224147000}'),i={name:"de/free-cloud/agnes-ai.md"};function r(l,e,d,s,g,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>Multimodaler Dienst von Sapiens AI (Singapur): ein OpenAI-kompatibles Gateway für <strong>Text, Bild und Video</strong>. <strong>Free Access</strong> eignet sich ohne bezahlten Key zum Chatten und Bildtesten; Kontingente und Limits laut Konsole.</p><h2 id="website-einstiege" tabindex="-1">Website &amp; Einstiege <a class="header-anchor" href="#website-einstiege" aria-label="Permalink to &quot;Website &amp; Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ressource</th><th>Adresse</th></tr></thead><tbody><tr><td>International</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>China</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API-Konsole (Registrierung / Key)</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Entwicklerdocs</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>Modellkatalog (GitHub)</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>Region: internationale oder China-Site; <strong>API Key und Base URL laut aktueller Konsole / Doku</strong>.</p><h2 id="free-access-holen" tabindex="-1">Free Access holen <a class="header-anchor" href="#free-access-holen" aria-label="Permalink to &quot;Free Access holen&quot;">​</a></h2><ol><li><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a> registrieren und anmelden (oft E-Mail; Karte laut Seite).</li><li>Entwicklerkonsole → <strong>API Keys</strong> → Key erstellen und kopieren (meist <code>sk-</code>).</li><li>In MiniTavern <strong>Custom (OpenAI)</strong> (Chat) oder <strong>Custom (OpenAI Images)</strong> (Bild) mit Base URL und Key — siehe unten.</li></ol><table tabindex="0"><thead><tr><th>Punkt</th><th>Hinweis</th></tr></thead><tbody><tr><td>Free</td><td><strong>Free Access</strong>: Kern-Flash-Serie kostenlos (RPM / Fair-Use), persönlich / Demo</td></tr><tr><td>Upgrade</td><td><strong>Token Plan</strong>: höheres TPS / Monatskontingent für Produktion (optional)</td></tr><tr><td>Limits (Free)</td><td>Text ca. <strong>20 RPM</strong>; Bild nach Auflösung (1K ca. 20 RPM, höher strenger); Video ca. <strong>1 RPM</strong> (<a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>)</td></tr><tr><td>Kreditkarte</td><td>Free Access meist ohne; kommerziell / höhere Limits → Token Plan</td></tr></tbody></table><blockquote><p>Policies ändern sich. Zeigt die Konsole Token Plan oder 429, gelten Website und Kontorechte.</p></blockquote><h2 id="modellliste" tabindex="-1">Modellliste <a class="header-anchor" href="#modellliste" aria-label="Permalink to &quot;Modellliste&quot;">​</a></h2><p>Häufige IDs aus öffentlicher Doku und Katalog (<strong>Groß-/Kleinschreibung beachten</strong>). Flash meist Free; <strong>Pro</strong> meist bezahlt.</p><h3 id="text-chat-vision" tabindex="-1">Text (Chat / Vision) <a class="header-anchor" href="#text-chat-vision" aria-label="Permalink to &quot;Text (Chat / Vision)&quot;">​</a></h3><p>Chat Completions: <code>POST /v1/chat/completions</code>. In MiniTavern <strong>Custom (OpenAI)</strong>.</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>empfohlen: Chat, Code, Tools, Multi-Turn, Bildverständnis; Kontext ~512K</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>Vorgänger-Flash, Reserve</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>bezahltes Reasoning — <strong>nicht als Free</strong></td></tr></tbody></table><h3 id="bild-text-to-image-image-to-image" tabindex="-1">Bild (Text-to-Image / Image-to-Image) <a class="header-anchor" href="#bild-text-to-image-image-to-image" aria-label="Permalink to &quot;Bild (Text-to-Image / Image-to-Image)&quot;">​</a></h3><p>Images: Text- und Image-to-Image über <code>POST /v1/images/generations</code> (Image-to-Image mit <code>image</code> im Body — <strong>nicht</strong> OpenAI <code>/images/edits</code>). MiniTavern <strong>Custom (OpenAI Images)</strong>, Base URL <code>https://apihub.agnes-ai.com/v1</code>; Custom-Protokoll routet so, auch Tests mit Referenzbild über generations.</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>empfohlen: dichte Generierung/Editing, flexible Größen</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>Text-/Image-to-Image, URL oder Base64</td></tr></tbody></table><h3 id="video-text-image-to-video" tabindex="-1">Video (Text-/Image-to-Video) <a class="header-anchor" href="#video-text-image-to-video" aria-label="Permalink to &quot;Video (Text-/Image-to-Video)&quot;">​</a></h3><p>Videos: <code>POST /v1/videos</code> (async). Häufige IDs:</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>Text-/Image-to-Video, Multi-Image/Keyframes usw.</td></tr><tr><td><code>agnes-video-v2.5</code> (oder Video 2.5 in der Doku)</td><td>neuere Video-API laut <a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">offizieller Videodoku</a></td></tr></tbody></table><p>MiniTavern hat <strong>derzeit keinen Video-Einstieg</strong>; Tabelle nur zum Abgleich. Chat und Bild: Flash Text-/Bildmodelle.</p><h2 id="eintrag-in-minitavern" tabindex="-1">Eintrag in MiniTavern <a class="header-anchor" href="#eintrag-in-minitavern" aria-label="Permalink to &quot;Eintrag in MiniTavern&quot;">​</a></h2><p>Allgemein: <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>.</p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Pfad: <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong></p><ol><li>Plattform <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://apihub.agnes-ai.com/v1</code></li><li>API Key einfügen</li><li>Modell-ID <code>agnes-2.5-flash</code> (oder anderes Textmodell aus der Konsole)</li><li><strong>Testen</strong> → bei Erfolg als Standard</li></ol><h3 id="bild" tabindex="-1">Bild <a class="header-anchor" href="#bild" aria-label="Permalink to &quot;Bild&quot;">​</a></h3><p>Pfad: <strong>Einstellungen → Bildgenerierung → Bildverbindung</strong></p><ol><li>Plattform <strong>Custom (OpenAI Images)</strong></li><li>Base URL wie oben</li><li>Derselbe Key; Modell z. B. <code>agnes-image-2.1-flash</code></li><li>Nach Test für <code>/imagine</code> oder Bild-Einstiege</li></ol><p>Chat und Bild getrennt möglich: z. B. Chat <code>agnes-2.5-flash</code>, Bild <code>agnes-image-2.1-flash</code>.</p><h2 id="verwandte-kapitel" tabindex="-1">Verwandte Kapitel <a class="header-anchor" href="#verwandte-kapitel" aria-label="Permalink to &quot;Verwandte Kapitel&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud Übersicht</a> — andere Free-/Trial-Kontingente</li><li><a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Bildgenerierung</a></li><li><a href="/ultra_guides/de/manual/model-link">Modellverbindung</a></li><li><a href="/ultra_guides/de/local/image-gen/">Bildmodelle lokal</a> — A1111 / ComfyUI</li></ul>',32)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
